import torch


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    if dtype.is_floating_point:
        x = torch.empty(shape, dtype=dtype, device=device).uniform_(0.99, 1.01)
    elif dtype is torch.bool:
        x = torch.randint(0, 2, shape, dtype=torch.int8, device="cpu").to(
            device, dtype=dtype
        )
    elif dtype is torch.uint8:
        x = torch.randint(0, 4, shape, dtype=dtype, device="cpu").to(device)
    else:
        x = torch.randint(-3, 4, shape, dtype=dtype, device="cpu").to(device)
    return {"x": x}


def run(x, dim):
    npu = getattr(torch, "npu", None)
    if x.dtype is torch.bool and npu is not None and npu.is_available():
        return torch.cumprod(x.to(torch.uint8), dim=dim)
    return torch.cumprod(x, dim=dim)


def run_correctness(x, dim):
    if x.dtype is torch.bool:
        ref = x.to(torch.uint8)
    elif x.dtype in (torch.float16, torch.bfloat16):
        ref = x.float()
    else:
        ref = x
    output = torch.cumprod(ref, dim=dim)
    if x.is_floating_point():
        output = output.to(x.dtype)
    return output
